"""The F01 game-folder and text fixtures (06-acceptance.md §5.1, §5.5), built by one script.

Run ``python tests/fixtures/F01/asset_fixtures.py`` to (re)generate the committed files under
``tests/fixtures/F01/games/`` and ``tests/fixtures/F01/text/``. Images are drawn with
pygame; WebP and GIF files are written by the small encoders below, because pygame cannot
save those formats. Random bytes come from ``random.Random(<seed>)`` with the seeds of §5.1.
The size-bomb headers (B1–B3) and ``images/big.png`` are generated by the tests instead.

The fonts are copies of OFL fonts from the official Noto release archives (see
``games/assets/fonts/SOURCE.txt``); this script copies ``engine/data/fonts/NotoSans-Regular.ttf``
and expects the two Noto Serif files to be present already.
"""

import os
import random
import shutil
import struct
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
GAMES = HERE / "games"
TEXT = HERE / "text"
REPO = HERE.parent.parent.parent
BUNDLED_FONT = REPO / "engine" / "data" / "fonts" / "NotoSans-Regular.ttf"

RGBA_BLUE = (0x33, 0x66, 0xCC, 255)


# --- WebP ---------------------------------------------------------------------------------

def _riff_webp(chunk_id: bytes, payload: bytes) -> bytes:
    if len(payload) % 2:
        payload += b"\x00"
    chunk = chunk_id + struct.pack("<I", len(payload)) + payload
    return b"RIFF" + struct.pack("<I", 4 + len(chunk)) + b"WEBP" + chunk


class _BitWriter:
    """LSB-first bit packing (the VP8L bitstream order)."""

    def __init__(self) -> None:
        self.value = 0
        self.count = 0

    def write(self, bits: int, n: int) -> None:
        self.value |= (bits & ((1 << n) - 1)) << self.count
        self.count += n

    def to_bytes(self) -> bytes:
        return self.value.to_bytes((self.count + 7) // 8, "little")


def webp_lossless_two_colors(width: int, height: int, pixel_is_second) -> bytes:
    """A VP8L (lossless) WebP of transparent black and #3366CC, using "simple" prefix codes:
    no transforms, no color cache, one prefix-code group. ``pixel_is_second(x, y)``."""
    bits = _BitWriter()
    bits.write(0x2F, 8)                      # signature
    bits.write(width - 1, 14)
    bits.write(height - 1, 14)
    bits.write(1, 1)                         # alpha is used
    bits.write(0, 3)                         # version 0
    bits.write(0, 1)                         # no transform
    bits.write(0, 1)                         # no color cache
    bits.write(0, 1)                         # no meta prefix codes
    # Green, red, blue, alpha: two symbols each (0 and the colour's value) → 1-bit codes.
    for value in (RGBA_BLUE[1], RGBA_BLUE[0], RGBA_BLUE[2], RGBA_BLUE[3]):
        bits.write(1, 1)                     # simple code
        bits.write(1, 1)                     # two symbols
        bits.write(0, 1)                     # first symbol uses 1 bit
        bits.write(0, 1)                     # symbol 0
        bits.write(value, 8)                 # second symbol
    bits.write(1, 1)                         # distance code: simple, one symbol (0)
    bits.write(0, 1)
    bits.write(0, 1)
    bits.write(0, 1)
    for y in range(height):
        for x in range(width):
            code = 1 if pixel_is_second(x, y) else 0
            bits.write(code, 1)              # green
            bits.write(code, 1)              # red
            bits.write(code, 1)              # blue
            bits.write(code, 1)              # alpha
    return _riff_webp(b"VP8L", bits.to_bytes())


def webp_lossy_flat(width: int, height: int) -> bytes:
    """A VP8 (lossy) key frame whose partitions are all zero bytes. A boolean decoder
    reading zeros decodes every flag and literal as 0: no segmentation, no filter,
    quantizer 0, no probability updates, B_PRED with B_DC_PRED sub-blocks and DC_PRED
    chroma, and an end-of-block token first in every block. The picture is therefore
    the prediction alone, a flat mid gray. The zero padding is long enough that neither
    partition reaches its end."""
    first_partition = bytes(4096)
    tokens = bytes(4096)
    tag = (len(first_partition) << 5) | (1 << 4) | (0 << 1) | 0   # show_frame, version 0, key
    header = struct.pack("<I", tag)[:3] + b"\x9d\x01\x2a" + struct.pack("<HH", width, height)
    return _riff_webp(b"VP8 ", header + first_partition + tokens)


# --- GIF ----------------------------------------------------------------------------------

def gif_two_frames(size: int = 16) -> bytes:
    """A 2-frame GIF89a. The LZW stream sends a clear code before every pixel pair, so the
    code width never grows past 3 bits."""
    def lzw(pixels: list[int]) -> bytes:
        bits = _BitWriter()
        for i in range(0, len(pixels), 2):
            bits.write(4, 3)                 # clear code (min code size 2)
            for pixel in pixels[i:i + 2]:
                bits.write(pixel, 3)
        bits.write(5, 3)                     # end of information
        data = bits.to_bytes()
        blocks = b"".join(bytes([len(data[i:i + 255])]) + data[i:i + 255]
                          for i in range(0, len(data), 255))
        return b"\x02" + blocks + b"\x00"

    out = b"GIF89a" + struct.pack("<HH", size, size) + b"\x80\x00\x00"
    out += b"\xff\x00\x00" + b"\x00\x00\xff"                        # red, blue
    out += b"\x21\xff\x0bNETSCAPE2.0\x03\x01\x00\x00\x00"            # loop forever
    for frame in range(2):
        out += b"\x21\xf9\x04\x00\x0a\x00\x00\x00"                  # 0.1 s per frame
        out += b"\x2c" + struct.pack("<HHHH", 0, 0, size, size) + b"\x00"
        out += lzw([(frame + x // 4) % 2 for _ in range(size) for x in range(size)])
    return out + b"\x3b"


# --- pygame-drawn images ------------------------------------------------------------------

def _pygame():
    os.environ.setdefault("SDL_VIDEODRIVER", "dummy")
    os.environ.setdefault("PYGAME_HIDE_SUPPORT_PROMPT", "1")
    import pygame
    pygame.init()
    return pygame


def rgba_surface(pygame):
    surface = pygame.Surface((64, 64), pygame.SRCALPHA, 32)
    surface.fill((0, 0, 0, 0))
    surface.fill(RGBA_BLUE, (32, 0, 32, 64))
    return surface


def solid(pygame, size, color):
    surface = pygame.Surface(size)
    surface.fill(color)
    return surface


def noise_photo(pygame, size, seed):
    rng = random.Random(seed)
    surface = pygame.Surface(size)
    width, height = size
    for y in range(0, height, 4):
        for x in range(0, width, 4):
            base = (x * 255 // width, y * 255 // height, 128)
            surface.fill(tuple(min(255, max(0, c + rng.randint(-30, 30))) for c in base),
                         (x, y, 4, 4))
    return surface


# --- text ---------------------------------------------------------------------------------

WORDS = ("lantern paper street rain window evening quiet music letter garden river "
         "morning shadow memory station winter harbor festival bridge library market "
         "candle meadow whisper journey promise silver mountain velvet orchard harmony "
         "Maple Willow Morning Wonder Moonlight Meadow Mirror Wanderer Melody Wildflower").split()


def paragraph_text() -> str:
    """300 characters: words, one 60-character word with no spaces, one explicit newline."""
    long_word = ("Supercalifragilistic" * 3)[:60]
    head = ("The paper lanterns swayed above the quiet street while the rain kept falling "
            "on the old wooden bridge near the harbor.\n")
    text = head + long_word + " "
    rng = random.Random(7)
    while len(text) < 300:
        text += rng.choice(WORDS).lower() + " "
    text = text[:300]
    return text[:299] + "." if text.endswith(" ") else text


def long_message_text() -> str:
    """5,000 characters of words separated by single spaces (AC-F01-79 (c))."""
    rng = random.Random(5000)
    text = ""
    while len(text) < 5000:
        text += rng.choice(WORDS).lower() + " "
    text = text[:5000]
    return text[:4999] + "." if text.endswith(" ") else text


def long_word_text() -> str:
    """One 5,000-character string with no spaces (AC-F01-79 (d))."""
    return ("Supercalifragilistic" * 250)[:5000]


def lines300(pygame) -> str:
    """300 distinct lines of 60–70 characters that lay out to about 1,120 canvas units at
    28 px in Noto Sans (AC-F01-157)."""
    font = pygame.font.Font(str(BUNDLED_FONT), 28)
    rng = random.Random(300)
    lines: list[str] = []
    seen: set[str] = set()
    while len(lines) < 300:
        words: list[str] = []
        while len(" ".join(words)) < 60:
            words.append(rng.choice(WORDS))
        line = " ".join(words)
        if len(line) > 70 or line in seen:
            continue
        if not 1040 <= font.size(line)[0] <= 1200:
            continue
        seen.add(line)
        lines.append(line)
    return "\n".join(lines) + "\n"


# --- build --------------------------------------------------------------------------------

def build() -> None:
    pygame = _pygame()
    serif_ttf = HERE / "games" / "unicode" / "fonts" / "フォント.ttf"
    serif_otf = HERE / "games" / "assets" / "fonts" / "test.otf"
    for needed in (serif_ttf, serif_otf):
        if not needed.is_file():
            sys.exit(f"missing {needed}: copy it from the Noto Serif v2.015 release first")

    minimal = GAMES / "minimal"
    minimal.mkdir(parents=True, exist_ok=True)
    (minimal / "config.toml").write_bytes(b'[game]\ntitle = "Fixture Game"\nversion = "9.9.9"\n')

    unicode_game = GAMES / "unicode"
    (unicode_game / "images" / "背景").mkdir(parents=True, exist_ok=True)
    (unicode_game / "config.toml").write_bytes('[game]\ntitle = "文芸部 Café Литература"\n'.encode())
    green = pygame.Surface((64, 32), pygame.SRCALPHA, 32)
    green.fill((0, 255, 0, 255))
    pygame.image.save(green, str(unicode_game / "images" / "背景" / "é.png"))

    assets = GAMES / "assets"
    images = assets / "images"
    for folder in (images / "bg", images / "dir.png", assets / "fonts", assets / "gui"):
        folder.mkdir(parents=True, exist_ok=True)
    (images / "dir.png" / ".gitkeep").write_bytes(b"")
    rgba = rgba_surface(pygame)
    pygame.image.save(rgba, str(images / "rgba.png"))
    pygame.image.save(noise_photo(pygame, (64, 64), 11), str(images / "photo.jpg"))
    (images / "lossless.webp").write_bytes(webp_lossless_two_colors(64, 64, lambda x, y: x >= 32))
    (images / "lossy.webp").write_bytes(webp_lossy_flat(64, 64))
    pygame.image.save(solid(pygame, (16, 16), (200, 120, 40)), str(images / "UPPER.PNG"))
    (images / "corrupt.png").write_bytes(random.Random(1).randbytes(512))
    (images / "truncated.png").write_bytes((images / "rgba.png").read_bytes()[:100])
    (images / "empty.png").write_bytes(b"")
    (images / "anim.gif").write_bytes(gif_two_frames())
    pygame.image.save(solid(pygame, (16, 16), (10, 200, 10)), str(images / "bitmap.bmp"))
    pygame.image.save(solid(pygame, (1280, 720), (0x44, 0x66, 0x88)), str(images / "bg" / "club.png"))
    pygame.image.save(noise_photo(pygame, (1280, 720), 12), str(images / "bg" / "lantern_street.png"))
    checker = pygame.Surface((2, 2))
    checker.fill((0, 0, 0))
    checker.set_at((1, 0), (255, 255, 255))
    checker.set_at((0, 1), (255, 255, 255))
    pygame.image.save(checker, str(images / "checker2.png"))
    shutil.copyfile(BUNDLED_FONT, assets / "fonts" / "test.ttf")
    (assets / "fonts" / "corrupt.ttf").write_bytes(random.Random(2).randbytes(256))
    pygame.image.save(solid(pygame, (64, 64), (255, 0, 0)), str(assets / "gui" / "lantern.png"))
    pygame.image.save(solid(pygame, (64, 64), (0, 255, 0)), str(assets / "gui" / "UPPER.PNG"))
    (assets / "gui" / "corrupt.png").write_bytes(random.Random(3).randbytes(128))

    TEXT.mkdir(parents=True, exist_ok=True)
    (TEXT / "paragraph.txt").write_bytes(paragraph_text().encode())
    (TEXT / "lines300.txt").write_bytes(lines300(pygame).encode())
    (TEXT / "long_message.txt").write_bytes(long_message_text().encode())
    (TEXT / "long_word.txt").write_bytes(long_word_text().encode())
    pygame.quit()


if __name__ == "__main__":
    build()
    print("fixtures written under", HERE)
